@patch
def get_vars(self:InteractiveShell, vs:list, literal=True):
    "Get variables from namespace."
    ns = self.user_ns
    def _maybe_eval(o):
        try: literal_eval(repr(o)); return o
        except: return str(o)
    return {v:_maybe_eval(ns[v]) if literal else str(ns[v]) for v in vs if v in ns}

